 'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const datefmt=d=>new Date((d||'2026-11-11')+'T12:00:00').toLocaleDateString('en-CA',{month:'long',day:'numeric',year:'numeric'}).toUpperCase();
const articles=window.TRIBUNE_ARTICLES||[];
const chafeAds=['chafe-a.webp','chafe-b.webp','chafe-c.webp'];
const image=(name,alt,cls='ad-image')=>`<img class="${cls}" src="assets/${name}" alt="${esc(alt)}" loading="lazy">`;
function chafeAd(){return `<aside class="ad illustrated-ad"><span class="kicker">A WORD FROM OUR COMPLETELY FICTIONAL SPONSOR</span><h2 class="ad-title">CHAFE-EASY!</h2><div class="ad-subtitle">MIRACLE THIGH OINTMENT</div>${image(chafeAds[0],'1950s illustrated fantasy football chafing cream advertisement')}<p class="ad-quote">“When your thighs rub harder than your fantasy team plays!”</p><div class="ad-price">ONLY 29¢</div><p class="disclaimer">Does not prevent bad trades, waiver overbids or public humiliation.</p><small>FICTIONAL PRODUCT · SATIRICAL ADVERTISEMENT</small><div class="ad-controls"><button type="button" id="rotateAd">See another ad ↻</button><span id="adCount">1 of 3</span></div></aside>`}
function tipPromo(){return `<aside class="tip-promo"><a href="?section=tipline" aria-label="Visit the Tribune Tip Line">${image('tipline-dual.webp','Vintage newspaper illustration inviting readers to report fantasy football disasters or dominance')}</a><a class="button-link" href="?section=tipline">SUBMIT YOUR STORY →</a><p class="fineprint">Click the illustration or the button to visit the Tip Line.</p></aside>`}
const ads={chafe:['DR. WAIVER’S MIRACLE CURE-ALL','One spoonful before waivers. A whole bottle after the results.'],summit:['GUARANTEED TRADE REGRET INSURANCE CO.','We can’t undo your trades. But we’ll pretend to care.'],frank:['HAGGERTY’S QUESTIONABLE JUDGMENT WHISKEY','Making bad decisions feel like good ones since 1927.']};
function miniAd(k){let [title,quote]=ads[k]||ads.chafe;return `<aside class="mini-ad"><span class="kicker">FICTIONAL SPONSOR · VINTAGE ADVERTISING</span><h3>${title}</h3><p>“${quote}”</p><small>Satire only. Not a real product or service.</small></aside>`}
function item(a){return `<a class="archive-item" href="article.html?id=${encodeURIComponent(a.id)}"><span class="kicker">${esc(a.category)} · ${esc(a.type)}${a.status==='preview'?' · VERDICT PENDING':''}</span><h3>${esc(a.title)}</h3><p>${esc(a.deck)}</p><span class="byline">${datefmt(a.date)} · READ STORY →</span></a>`}
function frontTipBanner(){return `<section class="front-tip-banner" aria-labelledby="frontTipTitle"><div class="front-tip-copy"><span class="front-tip-eyebrow">THE FOURTH & FUCKUP TRIBUNE · CONFIDENTIAL TIP LINE</span><h2 id="frontTipTitle">WITNESSED A FUCKUP?<br><em>OR ABSOLUTE FUCKING DOMINANCE?</em></h2><p>Every league has a story. Frank wants the receipts.</p><a class="front-tip-button" href="?section=tipline">SEND FRANK THE RECEIPTS <span aria-hidden="true">→</span></a><span class="front-tip-footnote">REAL LEAGUES. REAL EVIDENCE. NO BULLSHIT.</span></div></section>`}
function previousHeadlineMarkup(currentMain, selectedSecondary, selectedDate){
 // Show the two most recent distinct published main headlines below the current one.
 // Drafts never enter the public rotation; previously published stories remain in the archive.
 const rows=window.TRIBUNE_PUBLISHED_EDITIONS||[];
 const seen=new Set([(currentMain?.headline||'').trim().toLowerCase()]);
 const prior=[];
 if(selectedSecondary?.headline){
  const key=selectedSecondary.headline.trim().toLowerCase();
  if(!seen.has(key)){seen.add(key);prior.push({article:selectedSecondary,editionId:window.TRIBUNE_CURRENT_EDITION?.id,date:selectedDate});}
 }
 for(const row of rows){
  const old=row.content?.main;
  const key=(old?.headline||'').trim().toLowerCase();
  if(!key||seen.has(key))continue;
  seen.add(key);
  prior.push({article:old,editionId:row.id,date:row.edition_date});
  if(prior.length===2)break;
 }
 return prior.slice(0,2).map((entry,i)=>{
  const old=entry.article;
  const href='preview-editions.html?edition='+encodeURIComponent(entry.editionId);
  const kicker=i===0?'SECONDARY FRONT-PAGE HEADLINE':'THIRD FRONT-PAGE HEADLINE';
  return '<article class="front-secondary-headline" aria-label="'+(i===0?'Second':'Third')+' headline"><span class="kicker">'+kicker+'</span><div class="front-secondary-inner">'+(old.preview_image_url?'<a href="'+href+'"><img class="front-secondary-photo" src="'+esc(old.preview_image_url)+'" alt="Illustration for '+esc(old.headline)+'" loading="lazy"></a>':'')+'<div><h2><a href="'+href+'">'+esc(old.headline)+'</a></h2><p class="front-secondary-deck">'+esc(old.summary||'')+'</p><p class="byline">BY '+esc(old.author||'TRIBUNE STAFF')+' · '+datefmt(entry.date)+'</p><a class="readmore" href="'+href+'">READ THE INVESTIGATION →</a></div></div></article>';
 }).join('');
}

function standaloneStoryCards(){const rows=(window.TRIBUNE_STANDALONE_ARTICLES||[]).filter(a=>a.placement!=='main');if(!rows.length)return '';return '<section class="weekly-strip" aria-label="Latest standalone investigations"><span class="kicker">BREAKING FROM FRANK\'S DESK · BETWEEN EDITIONS</span><h2>LATEST INVESTIGATIONS</h2><div class="front-investigations">'+rows.slice(0,4).map(a=>'<a class="front-case" href="standalone-article.html?id='+encodeURIComponent(a.id)+'"><span class="kicker">'+esc((a.categories||[])[0]||'TRIBUNE EXCLUSIVE')+'</span><h3>'+esc(a.headline)+'</h3><p>'+esc(a.summary||'')+'</p><span class="byline">READ ARTICLE →</span></a>').join('')+'</div></section>';}

function frontEditorProof(p){
 const article=(a,tag)=>a?`<span class="kicker">${tag}</span><h3>${esc(a.headline)}</h3>${a.preview_image_url?`<img src="${esc(a.preview_image_url)}" alt="Illustration for ${esc(a.headline)}" style="width:100%;height:auto;max-height:260px;object-fit:contain;margin:10px 0">`:''}<p>${esc(a.summary||'')}</p>`:`<span class="kicker">${tag}</span><h3>STORY NOT ASSIGNED</h3><p>Select an article in the Edition Manager.</p>`;
 const main=p.main||{};
 const banner=p.published?'<div class="kicker">CURRENT PUBLISHED EDITION</div>':'<div class="kicker">CONFIDENTIAL EDITORIAL PROOF · NOT PUBLISHED</div>';
 const masthead=document.querySelector('.edition');
 if(masthead){const items=masthead.querySelectorAll('span');if(items[0])items[0].textContent='VOL. '+romanProof(p.volume)+' · NO. '+String(p.issue).padStart(3,'0');if(items[1])items[1].textContent=datefmt(p.date);}
 return banner+`${frontTipBanner()}<div class="front-layout"><section><span class="kicker">THE TRIBUNE INVESTIGATES · EDITION HEADLINE</span><h1 class="lead-headline">${esc(main.headline||'NO MAIN HEADLINE SELECTED')}</h1><p class="deck">${esc(main.summary||'')}</p><p class="byline">BY ${esc(main.author||'TRIBUNE STAFF')} · ${datefmt(p.date)}</p>${main.preview_image_url?`<figure style="margin:14px 0"><img src="${esc(main.preview_image_url)}" alt="Headline illustration for ${esc(main.headline||'featured story')}" style="width:100%;height:auto;max-height:480px;object-fit:contain"><figcaption class="photo-caption">Headline illustration · Private editorial proof</figcaption></figure>`:''}${main.story?`<p class="article-tease">${esc(main.story.slice(0,350))}</p>`:''}${p.mainImage?`<figure style="margin:18px 0"><img src="${esc(p.mainImage)}" alt="${esc(main.headline||'Main article image')}" style="width:100%;height:auto;max-height:450px;object-fit:contain"></figure>`:''}${p.published?`<a class="readmore" href="preview-editions.html?edition=${encodeURIComponent(p.id)}">READ THIS EDITION →</a><p><a href="preview-editions.html">PREVIOUS EDITIONS →</a></p>`:`<p class="photo-caption">Private proof only · This is not a published article</p>`}${previousHeadlineMarkup(main,p.secondary,p.date)}${standaloneStoryCards()}<div class="weekly-strip"><span class="kicker">THIS EDITION · INVESTIGATIONS</span><h2>THE BENCHWARMER BULLETIN</h2><div class="front-investigations"><div class="front-case">${article(p.left,'BENCHWARMER BULLETIN · LEFT')}</div><div class="front-case">${article(p.right,'BENCHWARMER BULLETIN · RIGHT')}</div></div></div><div class="bottom-grid"><div class="news-tile"><span class="kicker">LEAGUE DESK</span><h3><a href="?section=chafe">SLEEPING GIANT</a></h3><p>Keeper-league stories, plus the Chafe Mob team dispatch.</p></div><div class="news-tile"><span class="kicker">LEAGUE DESK</span><h3><a href="?section=summit">WESTFORT DYNASTY</a></h3><p>Dynasty-league news, plus the Summit Slayers team dispatch.</p></div><div class="news-tile"><span class="kicker">THE NEWSROOM</span><h3><a href="?section=shame">WALL OF SHAME</a></h3><p>The worst decisions deserve permanent ink.</p></div></div></section><aside class="sidebar">${chafeAd()}<section class="front-frank"><span class="kicker">THE MAN BEHIND THE HAMMER</span><h2>MEET THE BASTARD BEHIND THE BYLINE</h2><a href="frank.html" aria-label="Read Frank Haggerty’s biography">${image('frank.webp','Portrait of fictional editor Frank The Hammer Haggerty','front-frank-photo')}</a><p>Frank “The Hammer” Haggerty spent a lifetime investigating corruption, incompetence and spectacular displays of human stupidity.</p><p>Now he’s covering fantasy football.</p><p><strong>God help the managers.</strong></p><a class="readmore" href="frank.html">MEET FRANK →</a></section><section class="front-lower-tip"><h2 class="side-heading">SEND US YOUR EVIDENCE</h2>${tipPromo()}</section><h2 class="side-heading">EDITOR’S NOTICE</h2><p class="article-tease">Real fantasy football events, fictional reporting style. No submission is published without editorial review.</p></aside></div>`;
}
function romanProof(n){let out='';for(const [v,t] of [[1000,'M'],[900,'CM'],[500,'D'],[400,'CD'],[100,'C'],[90,'XC'],[50,'L'],[40,'XL'],[10,'X'],[9,'IX'],[5,'V'],[4,'IV'],[1,'I']])while(n>=v){out+=t;n-=v;}return out;}
function standaloneMainStory(){const mains=(window.TRIBUNE_STANDALONE_ARTICLES||[]).filter(x=>x.placement==='main').sort((a,b)=>new Date(b.published_at)-new Date(a.published_at));const a=mains[0];if(!a)return null;const old=articles.find(x=>x.featured);const href='standalone-article.html?id='+encodeURIComponent(a.id);const oldHref='article.html?id='+encodeURIComponent(old.id);const previous=mains.slice(1,3).map(x=>({headline:x.headline,summary:x.summary,author:x.author,image:x.image_url,date:x.published_at?.slice(0,10),href:'standalone-article.html?id='+encodeURIComponent(x.id)}));if(previous.length<2&&old&&!previous.some(x=>x.headline===old.title))previous.push({headline:old.title,summary:old.deck,author:old.author,image:'assets/Seventy-Four%20Dollars%2C%20One%20Catch.png',date:old.date,href:oldHref});const priorMarkup=previous.slice(0,2).map((x,i)=>'<article class="front-secondary-headline" aria-label="'+(i===0?'Second':'Third')+' headline"><span class="kicker">'+(i===0?'SECONDARY FRONT-PAGE HEADLINE · PREVIOUS INVESTIGATION':'THIRD FRONT-PAGE HEADLINE · PREVIOUS INVESTIGATION')+'</span><div class="front-secondary-inner">'+(x.image?'<a href="'+x.href+'"><img class="front-secondary-photo" src="'+esc(x.image)+'" alt="Illustration for '+esc(x.headline)+'" loading="lazy"></a>':'')+'<div><h2><a href="'+x.href+'">'+esc(x.headline)+'</a></h2><p class="front-secondary-deck">'+esc(x.summary||'')+'</p><p class="byline">BY '+esc(x.author||'TRIBUNE STAFF')+' · '+datefmt(x.date)+'</p><a class="readmore" href="'+x.href+'">READ THE INVESTIGATION →</a></div></div></article>').join('');return `${frontTipBanner()}<div class="front-layout"><section><span class="kicker">THE TRIBUNE INVESTIGATES · BREAKING FRONT-PAGE HEADLINE</span><h1 class="lead-headline">${esc(a.headline)}</h1><p class="deck">${esc(a.summary||'')}</p><p class="byline">BY ${esc(a.author||'FRANK “THE HAMMER” HAGGERTY')} · ${datefmt(a.published_at.slice(0,10))}</p>${a.image_url?'<figure style="margin:16px 0"><img src="'+esc(a.image_url)+'" alt="Illustration for '+esc(a.headline)+'" style="display:block;width:100%;height:auto;max-height:520px;object-fit:contain"></figure>':''}<a class="readmore" href="${href}">READ THE FULL INVESTIGATION →</a>${priorMarkup}${standaloneStoryCards()}<div class="weekly-strip"><span class="kicker">WEEK 9 · TWO INVESTIGATIONS PUBLISHED</span><h2>THE BENCHWARMER BULLETIN</h2><div class="front-investigations"><a class="front-case" href="article.html?id=right-hook-knocks-himself-out"><span class="kicker">SLEEPING GIANT</span><h3>THE RIGHT HOOK KNOCKS HIMSELF OUT</h3></a><a class="front-case" href="article.html?id=death-by-thirty-four-hundredths"><span class="kicker">WESTFORT DYNASTY</span><h3>DEATH BY THIRTY-FOUR HUNDREDTHS</h3></a></div></div><div class="bottom-grid"><div class="news-tile"><h3><a href="?section=chafe">SLEEPING GIANT</a></h3></div><div class="news-tile"><h3><a href="?section=summit">WESTFORT DYNASTY</a></h3></div><div class="news-tile"><h3><a href="?section=shame">WALL OF SHAME</a></h3></div></div></section><aside class="sidebar">${chafeAd()}<section class="front-frank"><span class="kicker">THE MAN BEHIND THE HAMMER</span><h2>MEET THE BASTARD BEHIND THE BYLINE</h2><a href="frank.html">${image('frank.webp','Portrait of Frank Haggerty','front-frank-photo')}</a><p>Frank “The Hammer” Haggerty spent a lifetime investigating corruption, incompetence and spectacular displays of human stupidity.</p><p>Now he’s covering fantasy football.</p><a class="readmore" href="frank.html">MEET FRANK →</a></section><section class="front-lower-tip"><h2 class="side-heading">SEND US YOUR EVIDENCE</h2>${tipPromo()}</section></aside></div>`;}
function front(){if(window.TRIBUNE_CURRENT_EDITION)return frontEditorProof(window.TRIBUNE_CURRENT_EDITION);if(new URLSearchParams(location.search).get('editor-proof')==='1'){try{const proof=JSON.parse(sessionStorage.getItem('tribune_editor_front_proof')||'null');if(proof&&proof.date)return frontEditorProof(proof);}catch(e){}}const standaloneLead=standaloneMainStory();if(standaloneLead)return standaloneLead;let a=articles.find(x=>x.featured);return `${frontTipBanner()}<div class="front-layout"><section><span class="kicker">THE TRIBUNE INVESTIGATES · CASE CLOSED · NO REFUNDS</span><h1 class="lead-headline">${esc(a.title)}</h1><p class="deck">${esc(a.deck)}</p><p class="byline">BY ${esc(a.author)} · ${datefmt(a.date)}</p><figure class="lead-graphic" style="display:block;padding:10px;margin:16px 0"><img src="assets/Seventy-Four%20Dollars%2C%20One%20Catch.png" alt="Vintage newspaper cartoon of Frank investigating the $74 Tutu Atwell waiver bid at a bowling alley" style="display:block;width:100%;height:auto" loading="eager"></figure><p class="photo-caption">THE SEVENTY-FOUR DOLLAR MAN · FINAL VERDICT: ONE CATCH, 4.10 POINTS</p><p class="article-tease">${esc(a.deck)}</p><a class="readmore" href="article.html?id=${encodeURIComponent(a.id)}">READ THE FULL INVESTIGATION →</a>${standaloneStoryCards()}<div class="weekly-strip"><span class="kicker">WEEK 9 · TWO INVESTIGATIONS PUBLISHED</span><h2>THE BENCHWARMER BULLETIN</h2><p>Frank Haggerty opens his first two case files: The Right Hook in Sleeping Giant and Carolina Reaper in Westfort Dynasty.</p><div class="front-investigations"><a href="article.html?id=right-hook-knocks-himself-out" class="front-case"><span class="kicker">SLEEPING GIANT · INVESTIGATION NO. 001</span><h3>THE RIGHT HOOK KNOCKS HIMSELF OUT</h3><p>A 24.22-point defeat. Stroud and Dell left watching from the bench.</p><span class="byline">READ THE INVESTIGATION →</span></a><a href="article.html?id=death-by-thirty-four-hundredths" class="front-case"><span class="kicker">WESTFORT DYNASTY · INVESTIGATION NO. 002</span><h3>DEATH BY THIRTY-FOUR HUNDREDTHS</h3><p>Carolina Reaper loses by 0.34 points. The bench holds the evidence.</p><span class="byline">READ THE INVESTIGATION →</span></a></div><a class="readmore" href="?section=bench">Visit the Bulletin →</a></div><div class="bottom-grid"><div class="news-tile"><span class="kicker">LEAGUE DESK</span><h3><a href="?section=chafe">SLEEPING GIANT</a></h3><p>Keeper-league stories, plus the Chafe Mob team dispatch.</p></div><div class="news-tile"><span class="kicker">LEAGUE DESK</span><h3><a href="?section=summit">WESTFORT DYNASTY</a></h3><p>Dynasty-league news, plus the Summit Slayers team dispatch.</p></div><div class="news-tile"><span class="kicker">THE NEWSROOM</span><h3><a href="?section=shame">WALL OF SHAME</a></h3><p>The worst decisions deserve permanent ink.</p></div></div></section><aside class="sidebar">${chafeAd()}<section class="front-frank"><span class="kicker">THE MAN BEHIND THE HAMMER</span><h2>MEET THE BASTARD BEHIND THE BYLINE</h2><a href="frank.html" aria-label="Read Frank Haggerty’s biography">${image('frank.webp','Portrait of fictional editor Frank The Hammer Haggerty','front-frank-photo')}</a><p>Frank “The Hammer” Haggerty spent a lifetime investigating corruption, incompetence and spectacular displays of human stupidity.</p><p>Now he’s covering fantasy football.</p><p><strong>God help the managers.</strong></p><a class="readmore" href="frank.html">MEET FRANK →</a></section><section class="front-lower-tip"><h2 class="side-heading">SEND US YOUR EVIDENCE</h2>${tipPromo()}</section><h2 class="side-heading">EDITOR’S NOTICE</h2><p class="article-tease">Real fantasy football events, fictional reporting style. No submission is published without editorial review.</p></aside></div>`}
const sectionInfo={chafe:['SLEEPING GIANT FANTASY FOOTBALL LEAGUE','Keeper-league reporting across the entire league. Chafe Mob gets its own recurring team dispatch.'],summit:['WESTFORT DYNASTY LEAGUE','Dynasty trades, rivalries and weekly triumphs and disasters across the entire league. Featuring the Summit Slayers team dispatch.'],frank:['FROM THE DESK OF FRANK HAGGERTY','Opinion, outrage and an unconfirmed number of whiskey stains.'],shame:['THE WALL OF SHAME','A permanent record of temporary lapses in judgment.'],archives:['THE TRIBUNE ARCHIVES','Every approved story preserved for posterity.'],tipline:['THE TRIBUNE TIP LINE','Report a catastrophe. Or a managerial masterpiece. The newsroom wants the evidence.'],bench:['THE BENCHWARMER BULLETIN','The weekly investigation into points that never made it into a starting lineup.']};
function league(name){let isChafe=name==='chafe',team=isChafe?'CHAFE MOB':'SUMMIT SLAYERS';let cat=isChafe?'Sleeping Giant':'Westfort Dynasty';let related=articles.filter(a=>a.category===cat||a.category===(isChafe?'Chafe Mob':'Summit Slayers'));return `<div class="feature-grid"><div class="feature"><span class="kicker">LEAGUE-WIDE REPORTING · WEEK 9</span><h3>THIS WEEK IN THE LEAGUE</h3><p>Frank's verified Week 9 investigations are now in print. The evidence is real; the language is entirely Haggerty's.</p><a href="?section=bench">Benchwarmer Bulletin →</a></div><div class="feature"><span class="kicker">RECURRING TEAM COLUMN</span><h3>${team} DISPATCH</h3><p>Starts, sits, player explosions, injuries and lineup regrets from ${team}. The team gets its own column without taking over league news.</p></div></div><h2 class="side-heading">INVESTIGATIONS & DEVELOPING STORIES</h2><div class="archive-list"></div>${miniAd(name)}`}
function tipline(){return `<div class="tip-hero">${image('tipline-dual.webp','Vintage Tribune invitation to report fantasy football disasters and dominance')}</div><div class="tip-status"><strong>SECURE NEWSROOM TIP LINE · NOW ACCEPTING REPORTS</strong><p>Send Frank your league's disasters, scandals or unlikely triumphs. Reports are delivered privately to the newsroom for editorial review. Nothing is published automatically.</p></div><section class="tip-form-wrap"><span class="kicker">CONFIDENTIAL CORRESPONDENCE · THE EDITOR'S DESK</span><h2>FILE YOUR REPORT</h2><p>Bring us the catastrophe. Bring us the brilliance. Above all, bring us the receipts.</p><form id="tipForm" novalidate><fieldset class="tip-radio"><legend>TYPE OF REPORT <span aria-hidden="true">*</span></legend><label><input type="radio" name="reportType" value="Report a Fuckup" checked> REPORT A FUCKUP</label><label><input type="radio" name="reportType" value="Report Absolute Fucking Dominance"> REPORT ABSOLUTE FUCKING DOMINANCE</label></fieldset><div class="tip-fields"><label>LEAGUE NAME <span>*</span><input name="league" required maxlength="120" placeholder="Name of your fantasy league"></label><label>TEAM BEING REPORTED <span>*</span><input name="team" required maxlength="120" placeholder="Team name, not a username"></label></div><label class="tip-label">WHAT THE HELL HAPPENED? <span>*</span><textarea name="story" required minlength="15" maxlength="6000" rows="6" placeholder="Tell Frank the story, including scores, lineup decisions, trades, dates or waiver bids..."></textarea></label><label class="tip-label">SCREENSHOT EVIDENCE (OPTIONAL)<input type="file" name="evidence" id="tipEvidence" accept="image/png,image/jpeg,image/webp" multiple><small>Choose up to 5 PNG, JPG or WebP screenshots, each under 10 MB. Hide private details before sharing. Screenshots are uploaded privately with your report.</small></label><div class="cf-turnstile" data-sitekey="0x4AAAAAAF9kauUDDPgQHrhO"></div><label class="tip-honeypot" aria-hidden="true">Leave this field empty<input name="fax_number" tabindex="-1" autocomplete="off"></label><div id="tipFiles" class="tip-file-summary" aria-live="polite">No screenshots selected.</div><label class="tip-label">CONTACT EMAIL (OPTIONAL)<input type="email" name="contact" maxlength="254" autocomplete="email" placeholder="your@email.com"></label><div class="tip-privacy"><strong>YOUR PRIVACY IS OUR PROMISE</strong><p>Your email address will be kept confidential and used solely to contact you if additional evidence or clarification is required to verify your submission. It will never be published, shared with third parties for marketing, or used for advertising or promotional purposes.</p><em>“I'm investigating your fantasy league, not your goddamn inbox.” — Frank “The Hammer” Haggerty</em><p class="fineprint">Reports are stored privately with Supabase for editorial review. You can request deletion by contacting the Tribune newsroom.</p></div><div class="tip-editor"><strong>A NOTICE FROM THE EDITOR</strong><p>Got evidence? Excellent. Don't want to give us your email? Fine by us.</p><p>Got no evidence but left an email? Frank might come knocking.</p><p>Got no evidence and no way to contact you? Congratulations. You've submitted a rumour to a newspaper that actually investigates shit.</p><strong>NO EVIDENCE. NO CONTACT. NO STORY.</strong><p>Even evidence-backed reports are verified and require editorial approval. Nothing is published automatically.</p></div><button type="submit">REVIEW MY REPORT →</button><p class="fineprint">A successful submission receives a case reference number. Nothing is published automatically.</p><div id="tipResult" role="status" aria-live="polite"></div></form></section>`}
const TIP_ENDPOINT='https://nlckcelwfcoszbvqyeyr.supabase.co/functions/v1/tribune-submit';
function initTiplineTurnstile(){
 const widget=document.querySelector('#tipForm .cf-turnstile');
 if(!widget)return;
 const status=document.getElementById('tipResult');
 let rendered=false;
 const render=()=>{
  if(rendered||!widget.isConnected||!window.turnstile)return;
  try{
   window.turnstile.render(widget,{sitekey:widget.dataset.sitekey,
    'error-callback':()=>{if(status){status.className='tip-result tip-error';status.textContent='Security verification could not load. Refresh the page and try again.';}},
    'expired-callback':()=>{if(status)status.textContent='Security verification expired. Please verify again.';}
   });
   rendered=true;
  }catch(err){console.warn('Turnstile rendering failed',err);}
 };
 const script=document.querySelector('script[src*="challenges.cloudflare.com/turnstile/v0/api.js"]');
 if(!script)return;
 const started=Date.now();
 const poll=()=>{
  if(rendered||!widget.isConnected)return;
  if(window.turnstile&&typeof window.turnstile.render==='function'){render();return;}
  if(Date.now()-started<12000)setTimeout(poll,350);
  else if(status){status.className='tip-result tip-error';status.textContent='Security verification unavailable. Refresh the page and try again.';}
 };
 poll();
}
function wireTipline(){const form=$('#tipForm');if(!form)return;const input=$('#tipEvidence'),summary=$('#tipFiles'),result=$('#tipResult');input.addEventListener('change',()=>{const files=[...input.files];summary.textContent=files.length?files.map(f=>f.name+' ('+(f.size/1048576).toFixed(1)+' MB)').join(' · '):'No screenshots selected.';result.textContent=''});form.addEventListener('submit',async e=>{e.preventDefault();const d=new FormData(form),files=[...input.files],email=String(d.get('contact')||'').trim(),story=String(d.get('story')||'').trim(),league=String(d.get('league')||'').trim(),team=String(d.get('team')||'').trim();const errors=[];if(!String(d.get('cf-turnstile-response')||''))errors.push('Complete the security verification.');if(!league||league.length>120||!team||team.length>120||story.length<15||story.length>6000)errors.push('Enter a league, team and story (15–6000 characters).');if(email&&(email.length>254||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)))errors.push('Enter a valid email address or leave it blank.');if(files.length>5||files.some(f=>f.size>10*1024*1024||!['image/png','image/jpeg','image/webp'].includes(f.type)))errors.push('Select up to five PNG, JPG or WebP files, each 10 MB or less.');if(errors.length){result.className='tip-result tip-error';result.textContent=errors.join(' ');return}const btn=form.querySelector('button[type=submit]');btn.disabled=true;btn.textContent='DELIVERING TO THE NEWSROOM…';result.className='tip-result';result.textContent='Securely sending your report…';try{const response=await fetch(TIP_ENDPOINT,{method:'POST',body:d});let body={};try{body=await response.json()}catch{}if(!response.ok)throw Error(body.error||'Newsroom delivery failed. Please try again later.');result.textContent='REPORT RECEIVED. Your confidential case reference is '+body.case_id+'. Frank will review the evidence before anything is published.';form.reset();if(window.turnstile)window.turnstile.reset();summary.textContent='No screenshots selected.'}catch(err){result.className='tip-result tip-error';result.textContent='NOT SENT: '+err.message}finally{btn.disabled=false;btn.textContent='SEND REPORT TO THE NEWSROOM →';result.scrollIntoView({behavior:'smooth',block:'nearest'})}})}

const departmentCategories={chafe:['Sleeping Giant League','Sleeping Giant','Chafe Mob'],summit:['Westfort Dynasty','Summit Slayers'],bench:['Benchwarmer Bulletin','Benchwarmers'],frank:["Frank's Desk"],shame:['Wall of Shame']};
const placementDepartment={sleeping:'chafe',westfort:'summit',shame:'shame','bulletin-left':'bench','bulletin-right':'bench'};
function publishedIndex(){
 const entries=[];
 const add=a=>{const title=String(a.headline||'').trim().toLowerCase().replace(/\s+/g,' ');if(!title)return;const duplicate=entries.find(x=>(a.identity&&x.identity===a.identity)||((!a.identity||!x.identity)&&String(x.headline||'').trim().toLowerCase().replace(/\s+/g,' ')===title));if(duplicate){duplicate.categories=[...new Set([...(duplicate.categories||[]),...(a.categories||[])])];duplicate.departments=[...new Set([...(duplicate.departments||[]),...(a.departments||[])])];duplicate.featuredDepartments=[...new Set([...(duplicate.featuredDepartments||[]),...(a.featuredDepartments||[])])];return;} entries.push(a);};
 for(const a of window.TRIBUNE_STANDALONE_ARTICLES||[])add({...a,identity:a.source_draft_id||a.id,date:a.published_at?.slice(0,10),href:'standalone-article.html?id='+encodeURIComponent(a.id),department:placementDepartment[a.placement],featured:!!placementDepartment[a.placement]});
 for(const e of window.TRIBUNE_PUBLISHED_EDITIONS||[]){
  const content=e.content||{},layout=content.department_layout||{},featured=layout['tribune-production-department-draft-ids']||{},support=layout['tribune-production-department-supporting']||{};
  for(const a of [content.main,content.secondary,content.left,content.right,...(content.department_articles||[])].filter(Boolean)){
   const departments=Object.keys(departmentCategories).filter(k=>featured[k]===a.id||(support[k]||[]).some(x=>x.id===a.id));
   if(a===content.left||a===content.right)departments.push('bench');
   add({...a,identity:a.id,date:e.edition_date,href:'preview-editions.html?edition='+encodeURIComponent(e.id),departments,featuredDepartments:Object.keys(featured).filter(k=>featured[k]===a.id)});
  }
 }
 for(const a of articles.filter(a=>a.status==='published'))add({identity:a.id,headline:a.title,summary:a.deck,author:a.author,categories:[a.category],date:a.date,href:'article.html?id='+encodeURIComponent(a.id),departments:['bench']});
 return entries.sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
}
function indexedCard(a,featured=false){return '<a class="archive-item" href="'+esc(a.href)+'"><span class="kicker">'+(featured?'DEPARTMENT HEADLINE · ':'')+esc((a.categories||[]).join(' · '))+'</span><h3>'+esc(a.headline)+'</h3><p>'+esc(a.summary||'')+'</p><span class="byline">'+datefmt(a.date)+' · READ STORY →</span></a>';}
function indexedDepartment(name){
 const matches=publishedIndex().filter(a=>a.department===name||a.departments?.includes(name)||(a.categories||[]).some(c=>(departmentCategories[name]||[]).includes(c)));
 const featured=matches.find(a=>a.department===name||a.featuredDepartments?.includes(name));
 return (featured?'<section class="feature"><span class="kicker">DEPARTMENT FEATURE</span>'+indexedCard(featured,true)+'</section>':'')+(matches.some(a=>a!==featured)?'<h2 class="side-heading">INVESTIGATIONS & DEVELOPING STORIES</h2><div class="archive-list">'+matches.filter(a=>a!==featured).map(a=>indexedCard(a)).join('')+'</div>':'');
}
function publishedCategorySection(){return '';}
function publishedDepartmentMarkup(name){return indexedDepartment(name);}
// Public newspaper pages must display published articles only. Draft layout data
// in browser storage is private editorial material, never reader-facing content.
function previewDepartmentLead(name){return publishedDepartmentMarkup(name)||'';}
function previewSupportingStories(name){return '';}
function section(name){let [title,desc]=sectionInfo[name];let top=`<span class="kicker">THE FOURTH & FUCKUP TRIBUNE · VOL. I</span><h1 class="section-title">${title}</h1><p class="section-intro">${desc}</p>`+previewDepartmentLead(name)+previewSupportingStories(name);
if(name==='frank')return top+publishedCategorySection("Frank's Desk")+`<section class="frank-intro"><span class="kicker">THE EDITOR · PERMANENT BIOGRAPHY</span><h2 class="frank-name">THE MAN BEHIND THE HAMMER</h2><div class="frank-desk-intro"><div class="frank-photo">${image('frank.webp','Frank The Hammer Haggerty in the Tribune newsroom','frank-portrait')}<p class="photo-caption">FRANK “THE HAMMER” HAGGERTY · EDITOR & INVESTIGATOR</p></div><div><p class="frank-subtitle">Investigative Journalist. Professional Pain in the Ass. Enemy of Bullshit.</p><p>Nobody knows exactly where Frank Haggerty came from. The few who claim they do generally stop talking when his name comes up.</p><p>His biography is a permanent fixture of the Tribune. The columns below change with each edition.</p><a class="readmore" href="frank.html">READ FRANK'S PERMANENT BIOGRAPHY →</a></div></div><blockquote class="frank-quote">“I don't give a fuck who you are. I give a fuck what's true.”<cite>— Frank “The Hammer” Haggerty</cite></blockquote></section><section class="frank-columns"><span class="kicker">FROM THE DESK · EDITORIAL COLUMNS</span><h2 class="side-heading">LATEST FROM FRANK'S DESK</h2><p class="article-tease">Frank's newest opinions, grudging praise and documented grievances appear here first. Older columns remain in the archives.</p><a class="readmore" href="?section=archives">BROWSE THE TRIBUNE ARCHIVES →</a></section><section class="frank-rule"><span class="kicker">THE HAMMER'S CODE · RULE NO. 1</span><h2>EVERY MANAGER DESERVES A FAIR INVESTIGATION.</h2><p>“Unfortunately, most of you stupid bastards keep providing evidence against yourselves.”</p><p class="photo-caption">SATIRICAL EDITORIAL CODE · FRANK FOLLOWS THE EVIDENCE, NOT THE MOB</p></section>${miniAd('frank')}`;
if(name==='chafe'||name==='summit')return top+publishedCategorySection(name==='chafe'?'Sleeping Giant League':'Westfort Dynasty')+league(name);
if(name==='tipline')return top+tipline();
if(name==='bench')return top+`<h2 class="side-heading">SEND FRANK THE NEXT CASE</h2><div class="tip-small">${tipPromo()}</div>`;
if(name==='shame')return top+publishedCategorySection('Wall of Shame')+`<div class="feature-grid"><div class="feature"><span class="kicker">CASE FILE 001 · UNDER INVESTIGATION</span><h3>THE $74 WAIVER BID</h3><p>A reported $74 bid for Tutu Atwell against a competing $5 offer. Full results remain pending.</p><a href="article.html?id=seventy-four-dollar-man">Read the preview →</a></div><div class="feature"><span class="kicker">READER NOMINATIONS</span><h3>THE NEXT HONOUREE</h3><p>We will add only verified incidents that deserve to be remembered.</p><a href="?section=tipline">Nominate a manager →</a></div></div>`;
if(name==='archives')return top+`<section class="feature"><h2>PREVIOUS NEWSPAPER EDITIONS</h2><a class="readmore" href="preview-editions.html">BROWSE EDITION ARCHIVES →</a></section><section class="feature"><span class="kicker">THE OBITUARIES · PERMANENT COMIC ARCHIVES</span><h2>COMIC ARCHIVES</h2><p>Four original series, each with its own permanent collection. Start at Volume 1 and follow every issue as the series grows.</p><a class="readmore" href="comics.html?view=archives">BROWSE ALL COMIC SERIES →</a></section><section class="archive-feature"><span class="kicker">THE SUNDAY HUDDLE · PERMANENT CROSSWORD ARCHIVES</span><h2>CROSSWORD ARCHIVES</h2><p>Every puzzle stays available, starting with No. 1: Fourth &amp; Long.</p><a class="readmore" href="crossword-archives.html">BROWSE CROSSWORDS →</a></section><h2 class="side-heading">NEWSPAPER ARCHIVES</h2><div class="archive-list">${publishedIndex().map(a=>indexedCard(a)).join('')}</div>`;
let filtered=name==='frank'?articles.filter(a=>a.category==="Frank's Desk"):articles;
return top+`<div class="archive-list">${filtered.map(item).join('')}</div>`+(name==='frank'?miniAd('frank'):'')}

